var success = StelSkyCultureMgr.setCurrentSkyCultureNameI18('Chinese');
if(success) {
    core.debug('Changed to Chinese sky culture');
} else {
    core.debug('Failed to change sky culture');
}

var localized = StelSkyCultureMgr.getCurrentSkyCultureNameI18();
core.debug('Active culture (i18n): ' + localized);

var cultureId = StelSkyCultureMgr.getCurrentSkyCultureID();
core.debug('Current culture ID: ' + cultureId);

// Alternative via Q_PROPERTY
var propId = core.getStelProperty('StelSkyCultureMgr.currentSkyCultureID');
core.debug('ID via property: ' + propId);

// Valid change
var ok = StelSkyCultureMgr.setCurrentSkyCultureID('egyptian');
core.debug('Egyptian activated: ' + ok);

// Invalid change — falls back to 'modern', returns false
var bad = StelSkyCultureMgr.setCurrentSkyCultureID('nonexistent_culture');
core.debug('Change failed: ' + bad);
core.debug('Active now: ' + StelSkyCultureMgr.getCurrentSkyCultureID());

// Restore
StelSkyCultureMgr.setCurrentSkyCultureID('modern');

var currentId = StelSkyCultureMgr.getCurrentSkyCultureID();
core.debug('Reloading: ' + currentId);
StelSkyCultureMgr.reloadSkyCulture();
core.debug('Reloaded. Active ID: ' + StelSkyCultureMgr.getCurrentSkyCultureID());

var boundaryType = StelSkyCultureMgr.getCurrentSkyCultureBoundariesType();
if(boundaryType === -1) {
    core.debug('No constellation boundaries defined (None)');
} else if(boundaryType === 0) {
    core.debug('Using IAU constellation boundaries');
} else if(boundaryType === 1) {
    core.debug('Using custom sky culture boundaries (Own)');
} else {
    core.debug('Unknown boundary type: ' + boundaryType);
}

var classification = StelSkyCultureMgr.getCurrentSkyCultureClassificationIdx();
var types = ['Incomplete', 'Personal', 'Traditional', 'Ethnographic', 'Historical', 'Single source', 'Comparative'];
core.debug('Sky culture classification: ' + types[classification]);

if(classification === 0) {
    core.debug('WARNING: This sky culture is marked as incomplete');
}

var htmlDesc = StelSkyCultureMgr.getCurrentSkyCultureHtmlClassification();
core.debug('Classification HTML: ' + htmlDesc);
// Can be displayed in a GUI dialog or info panel

var licenseHtml = StelSkyCultureMgr.getCurrentSkyCultureHtmlLicense();
if(licenseHtml) {
    core.output('License information: ' + licenseHtml);
} else {
    core.debug('No license information available');
}

var regionHtml = StelSkyCultureMgr.getCurrentSkyCultureHtmlRegion();
core.debug('Region info: ' + regionHtml);

// Check current region via the active sky culture ID
var id = StelSkyCultureMgr.getCurrentSkyCultureID();
core.debug('Is modern: ' + id.contains('modern'));

var fullDescription = StelSkyCultureMgr.getCurrentSkyCultureHtmlDescription();
core.debug('Full description (first 200 chars): ' + fullDescription.substring(0, 200));
// Can be displayed in a dialog or info panel

var narration = StelSkyCultureMgr.getCurrentSkyCultureNarration();
core.debug('Narration (first 200 chars): ' + narration.substring(0, 200));
// core.say(narration); // if speech output is available

var defaultId = StelSkyCultureMgr.getDefaultSkyCultureID();
core.debug('Default sky culture: ' + defaultId);

// Compare with current
var currentId = StelSkyCultureMgr.getCurrentSkyCultureID();
core.debug('Current vs Default: ' + currentId + ' / ' + defaultId);

// Set default for next startup
var success = StelSkyCultureMgr.setDefaultSkyCultureID('modern');
if(success) {
    core.debug('Default sky culture set to modern (saved automatically)');
} else {
    core.debug('Failed — invalid sky culture ID');
}

// Invalid case — returns false, no change
var bad = StelSkyCultureMgr.setDefaultSkyCultureID('does_not_exist');
core.debug('Invalid set returned: ' + bad);
core.debug('Default is still: ' + StelSkyCultureMgr.getDefaultSkyCultureID());

var cultures = StelSkyCultureMgr.getSkyCultureListEnglish();
core.debug('Available sky cultures: ' + cultures.length);
for (var i = 0; i < cultures.length; i++) {
    core.debug('  ' + (i+1) + '. ' + cultures[i]);
}

var cultures = StelSkyCultureMgr.getSkyCultureListI18();
core.debug('Localized culture names (sorted):');
for (var i = 0; i < cultures.length; i++) {
    core.debug('  ' + (i+1) + '. ' + cultures[i]);
}

// NOTE: QMultiMap support in JS may vary; use with caution on Qt6
var regionMap = StelSkyCultureMgr.getSkyCultureRegionMapI18();
core.debug('Region map retrieved. Type: ' + typeof regionMap);
// Prefer setCurrentSkyCultureID() for actual switching

// NOTE: QMap<QString, QPair<int,int>> may not convert cleanly in QJSEngine
var timeMap = StelSkyCultureMgr.getSkyCultureTimeLimitMapI18();
core.debug('Time limit map retrieved. Type: ' + typeof timeMap);
// Sentinels: -100000 = unknown, 9146 = present

var ids = StelSkyCultureMgr.getSkyCultureListIDs();
core.debug('Available IDs (' + ids.length + '):');
for (var i = 0; i < ids.length; i++) {
    core.debug('  ' + ids[i]);
}

// Use one to switch
if (ids.indexOf('egyptian') >= 0) {
    StelSkyCultureMgr.setCurrentSkyCultureID('egyptian');
}

// NOT RECOMMENDED — StelSkyCulture is a Q_GADGET
// Prefer the dedicated accessors instead:
var ids = StelSkyCultureMgr.getSkyCultureListIDs();
var english = StelSkyCultureMgr.getSkyCultureListEnglish();
core.debug('IDs: ' + ids.length + ', English names: ' + english.length);

// The map itself may be opaque on Qt6:
