var i18Map = StelSkyCultureMgr.getDirToI18Map();
core.debug('Retrieved ID→name map. Type: ' + typeof i18Map);

// Access pattern depends on QJSEngine conversion
var currentId = StelSkyCultureMgr.getCurrentSkyCultureID();
core.debug('Current ID: ' + currentId);
core.debug('Current localized: ' + StelSkyCultureMgr.getCurrentSkyCultureNameI18());

// STATIC — can be called without an instance
var style = StelSkyCultureMgr.convertCulturalDisplayStyleFromCSVstring('Native,IPA,Translated');
core.debug('Combined style enum: ' + style);

// Single token
var single = StelSkyCultureMgr.convertCulturalDisplayStyleFromCSVstring('native');
core.debug('Native only: ' + single);

// Unknown tokens are ignored
var bogus = StelSkyCultureMgr.convertCulturalDisplayStyleFromCSVstring('native,garbage,ipa');
