var style = StelSkyCultureMgr.convertCulturalDisplayStyleFromCSVstring('Native,IPA');
var csv = StelSkyCultureMgr.convertCulturalDisplayStyleToCSVstring(style);
core.debug('Round-trip: ' + csv);  // should contain native and ipa tokens

// Round-trip from the getter
var current = StelSkyCultureMgr.getScreenLabelStyleString();
core.debug('Screen style CSV: ' + current);

var style = StelSkyCultureMgr.getScreenLabelStyle();
core.debug('Screen label style enum: ' + style);

// Prefer the string version for readability
var styleStr = StelSkyCultureMgr.getScreenLabelStyleString();
core.debug('Screen label style: ' + styleStr);

var styleStr = StelSkyCultureMgr.getScreenLabelStyleString();
core.debug('Screen style: ' + styleStr);
if (styleStr.indexOf('native') >= 0) {
    core.debug('Native names are shown on screen');
}

// Read current
var before = StelSkyCultureMgr.getScreenLabelStyleString();
core.debug('Before: ' + before);

// Set new style (string form)
StelSkyCultureMgr.setScreenLabelStyle('Native,IPA,Translated');
core.debug('After: ' + StelSkyCultureMgr.getScreenLabelStyleString());

// Restore
StelSkyCultureMgr.setScreenLabelStyle(before);

var style = StelSkyCultureMgr.getInfoLabelStyle();
core.debug('Info label style enum: ' + style);
var styleStr = StelSkyCultureMgr.getInfoLabelStyleString();
core.debug('Info label style: ' + styleStr);

var before = StelSkyCultureMgr.getInfoLabelStyleString();
StelSkyCultureMgr.setInfoLabelStyle('Native,Translated');
core.debug('Info style now: ' + StelSkyCultureMgr.getInfoLabelStyleString());
StelSkyCultureMgr.setInfoLabelStyle(before);

var before = StelSkyCultureMgr.getZodiacLabelStyleString();
StelSkyCultureMgr.setZodiacLabelStyle('Native,IPA');
core.debug('Zodiac style now: ' + StelSkyCultureMgr.getZodiacLabelStyleString());
StelSkyCultureMgr.setZodiacLabelStyle(before);

var before = StelSkyCultureMgr.getLunarSystemLabelStyleString();
StelSkyCultureMgr.setLunarSystemLabelStyle('Native,Translated');
core.debug('Lunar style now: ' + StelSkyCultureMgr.getLunarSystemLabelStyleString());
StelSkyCultureMgr.setLunarSystemLabelStyle(before);

// Toggle
var current = StelSkyCultureMgr.getFlagOverrideUseCommonNames();
StelSkyCultureMgr.setFlagOverrideUseCommonNames(!current);
core.debug('Now: ' + StelSkyCultureMgr.getFlagOverrideUseCommonNames());

// Restore (NOTE: not persisted across restarts)
StelSkyCultureMgr.setFlagOverrideUseCommonNames(current);

var before = StelSkyCultureMgr.getFlagUseAbbreviatedNames();
StelSkyCultureMgr.setFlagUseAbbreviatedNames(!before);
core.debug('Abbreviated now: ' + StelSkyCultureMgr.getFlagUseAbbreviatedNames());
// This change IS saved across restarts
StelSkyCultureMgr.setFlagUseAbbreviatedNames(before);

var usesCommon = StelSkyCultureMgr.currentSkycultureUsesCommonNames();
core.debug('Current culture uses common names: ' + usesCommon);

// Compare with the raw flags
core.debug('Override flag: ' + StelSkyCultureMgr.getFlagOverrideUseCommonNames());
core.debug('Culture ID: ' + StelSkyCultureMgr.getCurrentSkyCultureID());

